pub(crate) fn units_left(o: &[i32]) -> bool {
    // Is a unit record left that the writer did not consume?
    let nd: i32 = o[(O_S_NDEF) as usize];
    let mut i: i32 = o[(O_S_UCUR) as usize];
    while i < nd {
        if o[((o.len() as i32) - (7 * (i + 1))) as usize] == 4 {
            return true;
        }
        i += 1;
    }
    return false;
}
pub(crate) fn units_strip(o: &mut [i32]) {
    // Drop every EV_UNITS event (the units pass then computes them).
    let n: i32 = o[(O_S_NEV) as usize];
    let mut k: i32 = 0;
    for i in 0..n {
        let e: i32 = O_S_FIRST + (EV_WORDS * i);
        if o[(e + 1) as usize] != EV_UNITS {
            let d: i32 = O_S_FIRST + (EV_WORDS * k);
            for j in 0..EV_WORDS {
                o[(d + j) as usize] = o[(e + j) as usize];
            }
            k += 1;
        }
    }
    o[(O_S_NEV) as usize] = k;
}
pub(crate) fn may_tag24(b: &[u8], start: i32, n: i32) -> i32 {
    // D286: can b[start, start + n) hold a tag 24 -- some head d8 18, d9 00 18,
    // da 00 00 00 18 or db 00 .. 00 18 anywhere (a byte search for a copy the
    // prefix writer did not write: content bytes may match too, which only costs
    // a visit)? 1 or 0.
    let end: i32 = start + n;
    let mut i: i32 = start;
    while i < end {
        let v: i32 = b[(i) as usize] as i32;
        if (v >= 216) && (v <= 219) {
            let w: i32 = 1 << (v - 216);
            let mut j: i32 = 1;
            let mut ok: bool = true;
            if (i + w) < end {
                while ok && (j < w) {
                    if (b[(i + j) as usize] as i32) != 0 {
                        ok = false;
                    }
                    j += 1;
                }
                if ok && ((b[(i + w) as usize] as i32) == 24) {
                    return 1;
                }
            }
        }
        i += 1;
    }
    return 0;
}
pub(crate) fn build_region(b: &[u8], o: &mut [i32], cb: &mut [u8], start: i32, n: i32, same: i32) -> i32 {
    // The copy's region (D286): for an accepted item that is its own DC form
    // (same != 0: only its key order or EC-sensitive keys differ from
    // deterministic) the input's bytes again, without the prefix writer; else
    // region's.
    if same == 0 {
        return region(cb, o, 0, n, n, 0, n + 64);
    }
    cb[(n) as usize..((n) + (n)) as usize].copy_from_slice(&b[(start) as usize..((start) + (n)) as usize]);
    o[(O_S_STOPP) as usize] = -1;
    o[(O_S_PSTOP) as usize] = -1;
    return 2 * n;
}
/// The canonical copy (D264) of the CHECKED item b[start, end) under the
/// scanner's verdict `refused` (0 accepted; else its duplicate refusal, if it is
/// one, in o[O_S_DUP*]): the input copied to cb[0, n), the copy written from
/// cb[n] (o[O_S_CBASE]), then for embeds 1 (tag-24 payloads) or 2 (every byte
/// string: the Program has `.cbor` controls) the embedded copies, then the units,
/// the events sorted. Answers the copy region's end (also o[O_VLEN]; padding
/// included), or -CODE_SCRATCH with o[O_VNEEDW] / o[O_VNEEDB] raised.
pub fn canon_build(b: &[u8], o: &mut [i32], cb: &mut [u8], start: i32, end: i32, embeds: i32, refused: i32) -> i32 {
    let n: i32 = end - start;
    let dk: i32 = o[(O_S_DUPK) as usize];
    let dp: i32 = o[(O_S_DUPP) as usize];
    let dofs: i32 = o[(O_S_DUPO) as usize];
    let all: i32 = embeds - 1;
    let mx0: i32 = o[(O_MAX_DEPTH) as usize];
    let su0: i32 = o[(O_S_UNITS) as usize];
    let vc0: i32 = o[(O_VCTL) as usize];
    let dl0: i32 = o[(O_S_DLOW) as usize];
    let mut uf: i32;
    uf = 0;
    // D286: an accepted item under a Program without .cbor whose scanner charged
    // units takes them from its records (kept below the events: the deferral list
    // stays); one with a tag 24 (its payloads' maps are the scanner's too) falls
    // back to the units pass below
    if ((refused == 0) && (embeds == 1)) && (su0 > 0) {
        uf = units_ready(o, start);
    }
    o[(O_S_NEV) as usize] = 0;
    o[(O_S_NSORT) as usize] = 0;
    o[(O_S_DLOW) as usize] = o.len() as i32;
    o[(O_S_UCUR) as usize] = -1;
    if uf == 1 {
        o[(O_S_DLOW) as usize] = dl0;
        o[(O_S_UCUR) as usize] = 0;
    }
    o[(O_S_RTOP) as usize] = O_S_FIRST + 8;
    o[(O_S_UNITS) as usize] = 0;
    if ((cb.len() as i32) < ((3 * n) + ((n >> 6) + 1024))) || ((o.len() as i32) < (O_S_FIRST + 256)) {
        o[(O_VNEEDB) as usize] = (3 * n) + ((n >> 6) + 4096);
        o[(O_VNEEDW) as usize] = O_S_FIRST + 1024;
        return -CODE_SCRATCH;
    }
    cb[(0) as usize..((0) + (n)) as usize].copy_from_slice(&b[(start) as usize..((start) + (n)) as usize]);
    o[(O_S_SBASE) as usize] = 0;
    o[(O_S_CBASE) as usize] = n;
    o[(O_S_DUPC) as usize] = -1;
    o[(O_S_DUPCO) as usize] = -1;
    if (refused != 0) && ((dk > 0) && ((dk & 4) == 0)) {
        o[(O_S_DUPP) as usize] = dp - start;
        o[(O_S_DUPO) as usize] = dofs - start;
    } else {
        o[(O_S_DUPP) as usize] = -1;
        o[(O_S_DUPO) as usize] = -1;
    }
    let mut same: i32;
    same = 0;
    o[(O_S_T24) as usize] = 0;
    if ((refused == 0) && ((vc0 & VC_NONDET) == 0)) && (embeds == 1) {
        same = 1;
    }
    let l: i32 = build_region(b, o, cb, start, n, same);
    let stop: i32 = o[(O_S_STOPP) as usize];
    let pstop: i32 = o[(O_S_PSTOP) as usize];
    let lim: i32 = lim_of(stop, l);
    if l < 0 {
        o[(O_VNEEDB) as usize] = (2 * (cb.len() as i32)) + 4096;
        return -CODE_SCRATCH;
    }
    if (refused != 0) && ((dk > 0) && ((dk & 4) == 0)) {
        let w: i32 = dup_event(o, dk);
        if w < 0 {
            return w;
        }
    }
    o[(O_S_DUPP) as usize] = -1;
    o[(O_S_DUPO) as usize] = -1;
    o[(O_VLEN) as usize] = l;
    o[(O_S_CBTOP) as usize] = l;
    let mut t24: i32;
    t24 = o[(O_S_T24) as usize];
    if same == 1 {
        t24 = may_tag24(cb, n, n);
    }
    if (uf == 1) && (t24 != 0) {
        units_strip(o);
        o[(O_S_DLOW) as usize] = o.len() as i32;
        uf = 0;
    }
    if (uf == 1) && (same == 1) {
        let wu: i32 = units_same(o, n);
        if wu < 0 {
            return wu;
        }
    }
    if uf == 1 {
        if units_left(o) {
            // never expected (the writer completes maps in the scanner's
            // order): the units pass computes them instead
            units_strip(o);
            o[(O_S_DLOW) as usize] = o.len() as i32;
            uf = 0;
        }
    }
    o[(O_S_UCUR) as usize] = -1;
    // D286: an accepted item without a tag 24 under a Program without .cbor
    // has no content to visit
    if (embeds > 0) && (((embeds == 2) || (refused != 0)) || (t24 != 0)) {
        let mut y: i32 = n;
        while y < lim {
            y = visit(b, o, cb, y, lim, all, 0, 0, mx0);
            if y == (-2) {
                y = lim;
            }
            if y < 0 {
                return y;
            }
        }
        // embedded copies are visited in turn (each may add more)
        let mut j: i32 = 0;
        while j < o[(O_S_NEV) as usize] {
            let e: i32 = O_S_FIRST + (EV_WORDS * j);
            if o[(e + 1) as usize] == EV_EMB {
                let elim: i32 = lim_of(o[(e + 5) as usize], o[(e + 4) as usize]);
                let mut y2: i32 = o[(e + 3) as usize];
                while y2 < elim {
                    y2 = visit(b, o, cb, y2, elim, all, 0, 0, o[(e + 7) as usize]);
                    if y2 == (-2) {
                        y2 = elim;
                    }
                    if y2 < 0 {
                        return y2;
                    }
                }
            }
            j += 1;
        }
    }
    // D277: the units, over the main copy and every embedded copy (the
    // events so far sorted for the lookups)
    ev_sort(o);
    // D286: the scanner's units are the units pass's (the same records and
    // comparisons, D277)
    if uf == 1 {
        o[(O_S_DLOW) as usize] = o.len() as i32;
        return l;
    }
    // D286: an accepted item with no marked map (the scanner charged no units
    // and saw no unsorted or EC-sensitive key: it marks under the same rules,
    // and a marked map charges at least 1) and no embedded copy has no units
    if ((refused == 0) && (su0 == 0)) && (((vc0 & (VC_UNSORTED | VC_ECS)) == 0) && (o[(O_S_NEV) as usize] == 0)) {
        return l;
    }
    let ne: i32 = o[(O_S_NEV) as usize];
    let ru: i32 = uvisit_seq(o, cb, n, lim, pstop, all);
    if ru < 0 {
        return ru;
    }
    for j2 in 0..ne {
        let e2: i32 = O_S_FIRST + (EV_WORDS * j2);
        if o[(e2 + 1) as usize] == EV_EMB {
            let rv: i32 = uvisit_seq(o, cb, o[(e2 + 3) as usize], lim_of(o[(e2 + 5) as usize], o[(e2 + 4) as usize]), o[(e2 + 6) as usize], all);
            if rv < 0 {
                return rv;
            }
        }
    }
    ev_sort(o);
    return l;
}
pub(crate) fn tskip_l(c: &[u8], o: &mut [i32], x: i32, lim: i32) -> i32 {
    // tskip over a copy that may be partial: 2^31 - 1 when the item holds the
    // region's stop lim (it is not complete there).
    if x == lim {
        return 2147483647;
    }
    let major: i32 = (i32::cast_unsigned(c[(x) as usize] as i32) >> 5).cast_signed();
    let q: i32 = targ(c, o, x);
    let lo: i32 = o[(O_LO) as usize];
    if (major == 4) || (major == 5) {
        let mut k: i32 = lo;
        let mut y: i32 = q;
        if major == 5 {
            k = 2 * lo;
        }
        for _i in 0..k {
            y = tskip_l(c, o, y, lim);
            if y == 2147483647 {
                return y;
            }
        }
        return y;
    }
    if major == 6 {
        return tskip_l(c, o, q, lim);
    }
    return tskip(c, o, x);
}
pub(crate) fn stop_src(o: &[i32], lim: i32) -> i32 {
    // The source start of the item stopped at lim (its EV_HEAD).
    let e: i32 = ev_find(o, lim, EV_HEAD);
    if e < 0 {
        return -1;
    }
    return o[(e + 6) as usize];
}
pub fn map_back_p(s: &[u8], c: &[u8], o: &mut [i32], xs: i32, xc: i32, x: i32, lim: i32) -> i32 {
    // A position x before the region's stop lim inside the copy c[xc, ...) of
    // the item s[xs, ...) (the copy may be partial) mapped to the source, in
    // lockstep (D264); the stop itself maps to the stopped item's source start.
    if (lim >= 0) && (x == lim) {
        return stop_src(o, lim);
    }
    let ce: i32 = tskip_l(c, o, xc, lim);
    let major: i32 = (i32::cast_unsigned(c[(xc) as usize] as i32) >> 5).cast_signed();
    let ch: i32 = targ(c, o, xc);
    if x >= ce {
        return tskip(s, o, xs);
    }
    if (x < ch) || ((major <= 1) || (major == 7)) {
        return xs;
    }
    if major <= 3 {
        return chunk_pos(s, o, xs, x - ch);
    }
    if major == 6 {
        let sx: i32 = targ(s, o, xs);
        return map_back_p(s, c, o, sx, ch, x, lim);
    }
    let mut sc: i32 = targ(s, o, xs);
    let mut cc: i32 = ch;
    loop {
        let cn: i32 = tskip_l(c, o, cc, lim);
        if x < cn {
            return map_back_p(s, c, o, sc, cc, x, lim);
        }
        cc = cn;
        sc = tskip(s, o, sc);
    }
}
pub(crate) fn map_seq_p(s: &[u8], c: &[u8], o: &mut [i32], ss: i32, cs: i32, ce: i32, x: i32, lim: i32) -> i32 {
    // map-back-p for a sequence: the copy c[cs, ce) of the items from s[ss].
    if (lim >= 0) && (x == lim) {
        return stop_src(o, lim);
    }
    let mut sc: i32 = ss;
    let mut cc: i32 = cs;
    while cc < ce {
        let cn: i32 = tskip_l(c, o, cc, lim);
        if x < cn {
            return map_back_p(s, c, o, sc, cc, x, lim);
        }
        cc = cn;
        sc = tskip(s, o, sc);
    }
    return sc;
}
pub fn vmap(b: &[u8], cb: &[u8], o: &mut [i32], start: i32, x: i32) -> i32 {
    // A position of the canonical copy (or of an embedded copy) mapped back to
    // the input b, whose item starts at start (events sorted).
    return vmap_x(b, cb, o, start, x, 0);
}
pub(crate) fn vmap_x(_b: &[u8], cb: &[u8], o: &mut [i32], start: i32, x: i32, src: i32) -> i32 {
    // vmap; src != 0: x is a SOURCE position (an embedded region's source is
    // the copy holding its byte string), so a position at the end of a
    // region's content belongs to that region, not to an embedded copy that
    // starts there -- as every position mapped out of an embedded copy is.
    let n: i32 = o[(O_S_CBASE) as usize];
    let ne: i32 = o[(O_S_NEV) as usize];
    let mut y: i32 = x;
    let mut strict: i32 = src;
    let mut guard: i32 = 0;
    while guard < 64 {
        guard += 1;
        let mut hit: i32 = -1;
        for i in 0..ne {
            let e: i32 = O_S_FIRST + (EV_WORDS * i);
            let cs: i32 = o[(e + 3) as usize];
            if (o[(e + 1) as usize] == EV_EMB) && (((y > cs) || ((y == cs) && (strict == 0))) && (y < o[(e + 4) as usize])) {
                hit = e;
            }
        }
        if hit < 0 {
            break;
        }
        strict = 1;
        y = map_seq_p(cb, cb, o, o[(hit) as usize], o[(hit + 3) as usize], o[(hit + 4) as usize], y, o[(hit + 5) as usize]);
    }
    if y < n {
        return start + y;
    }
    // the main stop is the first EV_HEAD in the main region, if any
    let mut mlim: i32 = -1;
    let vlen: i32 = o[(O_VLEN) as usize];
    for i2 in 0..ne {
        let e2: i32 = O_S_FIRST + (EV_WORDS * i2);
        if ((o[(e2 + 1) as usize] == EV_HEAD) && ((o[(e2) as usize] >= n) && (o[(e2) as usize] < vlen))) && (mlim < 0) {
            mlim = o[(e2) as usize];
        }
    }
    if y >= vlen {
        return start + n;
    }
    return start + map_back_p(cb, cb, o, 0, n, y, mlim);
}
pub fn vsource(b: &[u8], cb: &[u8], o: &mut [i32], start: i32, x: i32) -> i32 {
    // A replayed refusal's source offset mapped to the input: in the input's
    // copy directly, else (embedded content's source is a copy) by vmap.
    if x <= o[(O_S_CBASE) as usize] {
        return start + x;
    }
    return vmap_x(b, cb, o, start, x, 1);
}
